        WordEntity("c46", "Corporation", "ನಿಗಮ", "ಕಾನೂನು ರಚನೆಯ ಪ್ರತ್ಯೇಕ ಘಟಕವಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುವ ದೊಡ್ಡ ಸಂಸ್ಥೆ.", "ನಿಗಮ ಷೇರುದಾರರಿಗೆ ಸೀಮಿತ ಹೊಣೆಗಾರಿಕೆ.", "Commerce"),
        WordEntity("c47", "Cooperative", "ಸಹಕಾರ", "ಸದಸ್ಯರು ಸೇರಿ ಪರಸ್ಪರ ಸಹಾಯಕ್ಕಾಗಿ ನಡೆಸುವ ಸಂಸ್ಥೆ.", "ಹಾಲು ಸಹಕಾರ ಸಂಘ ರೈತರಿಗೆ ಸಹಾಯ.", "Commerce"),
        WordEntity("c48", "Monopoly", "ಏಕಸ್ವಾಮ್ಯ", "ಒಂದೇ ಕಂಪನಿ ಮಾರುಕಟ್ಟೆ ನಿಯಂತ್ರಿಸುವುದು.", "ಏಕಸ್ವಾಮ್ಯದಲ್ಲಿ ಸ್ಪರ್ಧೆ ಇಲ್ಲ.", "Commerce"),
        WordEntity("c49", "Oligopoly", "ಸ್ವಲ್ಪಸ್ವಾಮ್ಯ", "ಕೆಲವೇ ಕಂಪನಿಗಳು ಮಾರುಕಟ್ಟೆ ನಿಯಂತ್ರಿಸುವುದು.", "ಟೆಲಿಕಾಂ ಸ್ವಲ್ಪಸ್ವಾಮ್ಯ ಮಾರುಕಟ್ಟೆ.", "Commerce"),
        WordEntity("c50", "Competition", "ಸ್ಪರ್ಧೆ", "ವ್ಯಾಪಾರಗಳು ಗ್ರಾಹಕರನ್ನು ಆಕರ್ಷಿಸಲು ಪೈಪೋಟಿ.", "ಸ್ಪರ್ಧೆ ಗುಣಮಟ್ಟ ಸುಧಾರಿಸುತ್ತದೆ.", "Commerce"),
        WordEntity("c51", "Elasticity", "ಸ್ಥಿತಿಸ್ಥಾಪಕತೆ", "ಬೆಲೆ ಬದಲಾದಾಗ ಬೇಡಿಕೆ ಅಥವಾ ಪೂರೈಕೆ ಎಷ್ಟು ಬದಲಾಗುತ್ತದೆ.", "ಅವಶ್ಯ ವಸ್ತುಗಳ ಬೇಡಿಕೆ ಕಡಿಮೆ ಸ್ಥಿತಿಸ್ಥಾಪಕ.", "Commerce"),
        WordEntity("c52", "Opportunity Cost", "ಅವಕಾಶ ವೆಚ್ಚ", "ಒಂದು ಆಯ್ಕೆ ಮಾಡಿದಾಗ ಬಿಟ್ಟುಬಿಡುವ ಅತ್ಯುತ್ತಮ ಪರ್ಯಾಯ.", "ಕಾಲೇಜು ಹೋದರೆ ಕೆಲಸದ ಸಂಬಳ ಅವಕಾಶ ವೆಚ್ಚ.", "Commerce"),
