        WordEntity("c55", "Surplus", "ಹೆಚ್ಚುವರಿ", "ಆದಾಯ ವೆಚ್ಚಕ್ಕಿಂತ ಹೆಚ್ಚಿದ್ದಾಗ ಉಳಿಯುವ ಮೊತ್ತ.", "ಬಜೆಟ್ ಹೆಚ್ಚುವರಿ ಆರ್ಥಿಕ ಆರೋಗ್ಯ ಸೂಚಿಸುತ್ತದೆ.", "Commerce"),
